mapper.select:
SELECT a.application_user_id AS user_id , b.user_name AS employee_no , NVL(b.full_name_local,b.english_full_name) AS employee_name , c.system_code , c.module_code , a.program_id , c.program_name , a.html_inq_condition_object_id , a.html_inq_cond_object_type_code , a.initial_value1_text FROM LGCOM_USER_INQUIRY_CONDITION_N a , LGCOM_USER_M_V b , LGCOM_PROGRAM_M c WHERE a.application_user_id = b.application_user_id AND a.program_id = c.program_id
AND a.application_user_id = #{userId}
AND (b.full_name_local LIKE #{employeeName} || '%' OR b.english_full_name LIKE #{employeeName} || '%')
AND a.program_id = #{programId}
AND UPPER(c.program_name) LIKE UPPER(#{programName}) || '%'
ORDER BY a.application_user_id, a.program_id, a.html_inq_condition_object_id

mapper.delete:
DELETE FROM LGCOM_USER_INQUIRY_CONDITION_N
      WHERE application_user_id          = #{userId}
        AND program_id                   = #{programId}
        AND html_inq_condition_object_id = #{htmlInqConditionObjectId}
